<?php
require_once __DIR__.'/../../includes/auth.php'; require_once __DIR__.'/../../includes/csrf.php'; require_once __DIR__.'/../../config/database.php';
$a=require_permission('marks.edit'); if(!in_array($a['role_name']??'', ['admin','dept_admin','super_admin'],true)){http_response_code(403);exit('403 Forbidden');}
$id=(int)($_GET['entry_id']??0); $q=$pdo->query("SELECT fme.entry_id,fme.marks_obtained,fme.is_absent,s.student_name,s.roll_no,p.paper_code,p.paper_name,sub.subject_code,sub.subject_name,at.assessment_type_name,COALESCE(NULLIF(CASE WHEN LOWER(at.assessment_type_name) LIKE '%internal%' THEN psm.subject_max_internal WHEN LOWER(at.assessment_type_name) LIKE '%mid%' THEN psm.subject_max_midterm WHEN LOWER(at.assessment_type_name) LIKE '%final%' THEN psm.subject_max_final END,0),CASE WHEN LOWER(at.assessment_type_name) LIKE '%internal%' THEN p.max_internal WHEN LOWER(at.assessment_type_name) LIKE '%mid%' THEN p.max_midterm WHEN LOWER(at.assessment_type_name) LIKE '%final%' THEN p.max_final END,sfm.max_marks) max_marks FROM faculty_marks_entry fme JOIN students s ON s.student_id=fme.student_id JOIN papers p ON p.paper_id=fme.paper_id JOIN subjects sub ON sub.subject_id=fme.subject_id JOIN assessment_types at ON at.assessment_type_id=fme.assessment_type_id JOIN paper_subject_mapping psm ON psm.batch_id=s.batch_id AND psm.paper_id=fme.paper_id AND psm.subject_id=fme.subject_id LEFT JOIN subject_faculty_mapping sfm ON sfm.batch_id=s.batch_id AND sfm.subject_id=fme.subject_id AND sfm.faculty_id=fme.faculty_id WHERE fme.paper_id IS NOT NULL ORDER BY s.batch_id,p.paper_id,sub.subject_code,at.assessment_type_id,fme.entry_id"); $rows=$q->fetchAll(PDO::FETCH_ASSOC); $edit=null; foreach($rows as $r)if((int)$r['entry_id']===$id)$edit=$r; function fe($v){return htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');}
?><!doctype html><html><head><title>Full Marks Edit</title></head><body><h1>Full Marks Edit</h1><?php if($edit):?><form method="post" action="full_edit_save.php"><?=csrfField()?><input type="hidden" name="entry_id" value="<?=$id?>"><p><?=fe($edit['paper_name'])?> / <?=fe($edit['subject_name'])?> / <?=fe($edit['assessment_type_name'])?></p><p>Current: <?=((int)$edit['is_absent']?'Absent':fe($edit['marks_obtained']))?> | Maximum: <?=fe($edit['max_marks'])?></p><input type="number" name="new_marks" min="0" max="<?=fe($edit['max_marks'])?>" step="0.01" required><textarea name="reason" required minlength="3" placeholder="Correction reason"></textarea><button>Save</button></form><?php endif;?><table><tr><th>Paper</th><th>Subject</th><th>Assessment Type</th><th>Current Mark</th><th>Maximum Mark</th><th>Edit</th></tr><?php foreach($rows as $r):?><tr><td><?=fe($r['paper_name'])?></td><td><?=fe($r['subject_name'])?></td><td><?=fe($r['assessment_type_name'])?></td><td><?=((int)$r['is_absent']?'Absent':fe($r['marks_obtained']))?></td><td><?=fe($r['max_marks'])?></td><td><a href="?entry_id=<?=(int)$r['entry_id']?>">Edit</a></td></tr><?php endforeach;?></table></body></html>
